(function() {
    function easeOutExpo(t) {
        return t === 1 ? 1 : 1 - Math.pow(2, -10 * t);
    }

    function formatNumber(val, decimals, hasCommas) {
        var str = decimals > 0 ? val.toFixed(decimals) : Math.floor(val).toString();
        if (hasCommas) {
            var parts = str.split('.');
            parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            str = parts.join('.');
        }
        return str;
    }

    function animateValue(element, originalText) {
        var match = originalText.match(/^([^0-9]*)([0-9][0-9,.]*)(.*)$/);
        if (!match) return;

        var prefix = match[1] || '';
        var rawNumStr = match[2];
        var suffix = match[3] || '';
        var cleanNumStr = rawNumStr.replace(/,/g, '');
        var target = parseFloat(cleanNumStr);
        if (isNaN(target)) return;

        var isFloat = cleanNumStr.indexOf('.') !== -1;
        var decimals = isFloat ? cleanNumStr.split('.')[1].length : 0;
        var hasCommas = rawNumStr.indexOf(',') !== -1;
        var duration = 2000;
        var start = performance.now();

        function update(currentTime) {
            var elapsed = currentTime - start;
            var progress = Math.min(elapsed / duration, 1);
            var currentVal = target * easeOutExpo(progress);
            element.textContent = prefix + formatNumber(currentVal, decimals, hasCommas) + suffix;

            if (progress < 1) {
                requestAnimationFrame(update);
            } else {
                element.textContent = originalText;
            }
        }

        requestAnimationFrame(update);
    }

    function initStats(root) {
        if (!root || root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
        if (root.querySelector('[data-sl-edit-id]')) return;

        var grid = root.querySelector('.sl-stats-grid');
        if (!grid) return;

        var statElements = root.querySelectorAll('.sl-stat-number');
        if (!statElements.length) return;

        var hasAnimated = false;
        if (typeof IntersectionObserver === 'undefined') return;

        var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (entry.isIntersecting && !hasAnimated) {
                    hasAnimated = true;
                    statElements.forEach(function(el) { 
                        var originalText = el.textContent.trim();
                        if (!el.hasAttribute('contenteditable')) {
                            animateValue(el, originalText);
                        }
                    });
                    observer.disconnect();
                }
            });
        }, { threshold: 0.2 });

        observer.observe(grid);
    }

    function initAll() {
        document.querySelectorAll('.sl-stats-animated').forEach(initStats);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
